# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MÜMİNİN NİTELİKLERİ (ENFÂL, 2-4) VE İHLAS İLKESİ</text>\n  <!-- Sol: Muminin Ozellikleri -->\n  <rect x="25" y="42" width="330" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="190" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">GERÇEK MÜMİNLERİN ÖZELLİKLERİ</text>\n  <rect x="40" y="78" width="300" height="36" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="190" y="101" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">el-Mü\'min (Haşr, 23): Güven veren, inanan</text>\n  <text x="42" y="136" font-size="11.5" fill="#14532d">1. Allah anıldığında kalpleri saygıyla ürperir.</text>\n  <text x="42" y="156" font-size="11.5" fill="#14532d">2. Ayetler okunduğunda imanları güçlenir ve artar.</text>\n  <text x="42" y="176" font-size="11.5" fill="#14532d">3. Yalnızca Rablerine dayanıp tevekkül ederler.</text>\n  <text x="42" y="196" font-size="11.5" fill="#14532d">4. Namazlarını huşu içinde dosdoğru kılarlar.</text>\n  <text x="42" y="216" font-size="11.5" fill="#14532d">5. Kendilerine verilen rızıktan infak ederler.</text>\n  <!-- Sag: Ihlas -->\n  <rect x="375" y="42" width="300" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="525" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">İHLAS (SAMİMİYET) BİLİNCİ</text>\n  <rect x="392" y="78" width="266" height="46" rx="6" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="525" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">Zümer Suresi, 11. Ayet</text>\n  <text x="525" y="114" text-anchor="middle" font-size="11" fill="#1d4ed8">Dini yalnız Allah\'a halis kılarak kulluk etmek</text>\n  <text x="392" y="146" font-size="11.5" fill="#1e3a8a">• İbadetlerde yalnız Allah rızasını gözetmek.</text>\n  <text x="392" y="168" font-size="11.5" fill="#1e3a8a">• Gösterişten (riya) ve kibir duygusundan</text>\n  <text x="402" y="184" font-size="11.5" fill="#1e3a8a">tamamen arınmak.</text>\n  <text x="392" y="206" font-size="11.5" fill="#1e3a8a">• Özü ile sözü bir, dürüst ve güvenilir olmak.</text>\n  <text x="392" y="228" font-size="11.5" font-weight="bold" fill="#1d4ed8">• İhlasın zıddı: Riya (Gösteriş) ve Nifak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MÜNAFIK KAVRAMI VE HADİSTE BİLDİRİLEN NİFAK ALAMETLERİ</text>\n  <!-- Sol: Munafik Tanimi -->\n  <rect x="25" y="42" width="320" height="202" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">MÜNAFIK (İKİYÜZLÜ KİMSE)</text>\n  <rect x="42" y="78" width="286" height="46" rx="6" fill="#fde68a" stroke="#f59e0b"/>\n  <text x="185" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">Kalp: İnkâr (Küfür)  ≠  Dil: İkrar (İman İddiası)</text>\n  <text x="185" y="114" text-anchor="middle" font-size="11" fill="#92400e">İçi ile dışı bir olmayan, aldatıcı tutum</text>\n  <text x="42" y="146" font-size="11.5" fill="#78350f">• Tevbe, 67: Kötülüğü emreder, iyiliği engeller.</text>\n  <text x="42" y="168" font-size="11.5" fill="#78350f">• Cimridirler ve namaza üşenerek kalkarlar.</text>\n  <text x="42" y="190" font-size="11.5" fill="#78350f">• Islah edici göründükleri hâlde bozguncudurlar.</text>\n  <text x="42" y="214" font-size="11.5" font-weight="bold" fill="#b45309">• Dünyada Müslüman muamelesi görür, ahirette</text>\n  <text x="52" y="230" font-size="11.5" font-weight="bold" fill="#b45309">kalplerindeki inkâra göre cezalandırılırlar.</text>\n  <!-- Sag: 3 Alamet -->\n  <rect x="365" y="42" width="310" height="202" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">MÜNAFIKLIĞIN 3 ALAMETİ (BUHÂRÎ, ÎMÂN, 24)</text>\n  <rect x="385" y="82" width="270" height="40" rx="6" fill="#fee2e2" stroke="#ef4444"/>\n  <text x="520" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">1. Konuştuğu zaman YALAN söyler.</text>\n  <rect x="385" y="132" width="270" height="40" rx="6" fill="#fee2e2" stroke="#ef4444"/>\n  <text x="520" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">2. Söz verdiği zaman SÖZÜNDE DURMAZ.</text>\n  <rect x="385" y="182" width="270" height="40" rx="6" fill="#fee2e2" stroke="#ef4444"/>\n  <text x="520" y="206" text-anchor="middle" font-size="12" font-weight="bold" fill="#7f1d1d">3. Emanet edildiği zaman HIYANET eder.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KÂFİR, MÜŞRİK VE FASIK KAVRAMLARI İLE İMAN TERİMLERİ</text>\n  <!-- Kutu 1: Kafir ve Musrik -->\n  <rect x="20" y="42" width="220" height="202" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="130" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">KÂFİR VE MÜŞRİK</text>\n  <rect x="34" y="76" width="192" height="68" rx="6" fill="#fee2e2"/>\n  <text x="42" y="94" font-size="11" font-weight="bold" fill="#7f1d1d">• Kâfir (Küfür):</text>\n  <text x="46" y="110" font-size="10.8" fill="#991b1b">Hakikati örten, iman esaslarından</text>\n  <text x="46" y="126" font-size="10.8" fill="#991b1b">birini veya tamamını inkâr eden.</text>\n  <rect x="34" y="152" width="192" height="80" rx="6" fill="#fee2e2"/>\n  <text x="42" y="170" font-size="11" font-weight="bold" fill="#7f1d1d">• Müşrik (Şirk - Lokmân, 13):</text>\n  <text x="46" y="186" font-size="10.8" fill="#991b1b">Allah\'ın zatında, sıfatlarında</text>\n  <text x="46" y="202" font-size="10.8" fill="#991b1b">veya ibadette O\'na ortak koşan</text>\n  <text x="46" y="218" font-size="10.8" font-weight="bold" fill="#b91c1c">(En büyük zulüm - Nisâ, 48).</text>\n  <!-- Kutu 2: Fasik -->\n  <rect x="252" y="42" width="206" height="202" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="355" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">FASIK (FISK)</text>\n  <rect x="266" y="76" width="178" height="46" rx="6" fill="#ffedd5"/>\n  <text x="355" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#7c2d12">İtaatten Çıkan / Günahkâr</text>\n  <text x="355" y="111" text-anchor="middle" font-size="10.5" fill="#9a3412">Dinin Sınırlarını Aşan Kimse</text>\n  <text x="266" y="144" font-size="10.8" fill="#7c2d12">• Allah\'ın emirlerini çiğneyip</text>\n  <text x="274" y="160" font-size="10.8" fill="#7c2d12">büyük günah işleyen kimsedir.</text>\n  <text x="266" y="182" font-size="10.8" fill="#7c2d12">• Ehl-i sünnete göre günahı</text>\n  <text x="274" y="198" font-size="10.8" fill="#7c2d12">helal saymadıkça dinden</text>\n  <text x="274" y="214" font-size="10.8" font-weight="bold" fill="#c2410c">çıkmaz, günahkâr mümindir.</text>\n  <!-- Kutu 3: 1. Unite Kavramlari -->\n  <rect x="470" y="42" width="210" height="202" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">TEMEL İMAN KAVRAMLARI</text>\n  <text x="482" y="90" font-size="10.8" fill="#581c87">• <tspan font-weight="bold">İcmali İman:</tspan> Toptan ve özlü iman.</text>\n  <text x="482" y="110" font-size="10.8" fill="#581c87">• <tspan font-weight="bold">Tafsili İman:</tspan> Ayrıntılı iman.</text>\n  <text x="482" y="130" font-size="10.8" fill="#581c87">• <tspan font-weight="bold">Fıtrat:</tspan> Doğuştan inanma eğilimi.</text>\n  <text x="482" y="154" font-size="10.8" font-weight="bold" fill="#6b21a8">Hadis Türleri:</text>\n  <text x="486" y="172" font-size="10.5" fill="#581c87">- Ravi sayısına göre: Mütevatir,</text>\n  <text x="494" y="187" font-size="10.5" fill="#581c87">Meşhur, Âhâd hadis.</text>\n  <text x="486" y="206" font-size="10.5" fill="#581c87">- Sıhhatine göre: Sahih, Hasen</text>\n  <text x="494" y="221" font-size="10.5" fill="#581c87">ve Zayıf hadis.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
